python3 --version && python3 -c "
import importlib
for pkg in ['nltk', 'rouge_score', 'bert_score', 'numpy', 'sklearn']:
    try:
        m = importlib.import_module(pkg)
        print(f'{pkg}: available ({getattr(m, \"__version__\", \"?\")})')
    except ImportError:
        print(f'{pkg}: NOT available')
"

pip install rouge-score 2>&1 | tail -2; python3 -c "
import nltk
for res in ['punkt', 'wordnet', 'omw-1.4']:
    try:
        nltk.data.find(f'tokenizers/{res}' if res=='punkt' else f'corpora/{res}')
        print(f'{res}: available')
    except LookupError:
        print(f'{res}: missing')
"
